-- EMAILCENTER INITIAL PROJECT DATABASE, schema version 1
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE project_metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE applicant_profiles(id TEXT PRIMARY KEY, display_name TEXT NOT NULL, email TEXT, phone TEXT, address_json TEXT NOT NULL DEFAULT '{}', custom_fields_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE companies(id TEXT PRIMARY KEY, name TEXT NOT NULL, website TEXT, industry TEXT, address_json TEXT NOT NULL DEFAULT '{}', notes TEXT, custom_fields_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX idx_companies_name ON companies(name);
CREATE TABLE contacts(id TEXT PRIMARY KEY, first_name TEXT, last_name TEXT, display_name TEXT NOT NULL, email TEXT, phone TEXT, position TEXT, notes TEXT, custom_fields_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX idx_contacts_name ON contacts(display_name);
CREATE INDEX idx_contacts_email ON contacts(email);
CREATE TABLE company_contacts(company_id TEXT NOT NULL, contact_id TEXT NOT NULL, relationship_type TEXT, is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)), created_at TEXT NOT NULL, PRIMARY KEY(company_id,contact_id), FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE, FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE CASCADE);
CREATE TABLE job_postings(id TEXT PRIMARY KEY, company_id TEXT NOT NULL, title TEXT NOT NULL, reference_number TEXT, location TEXT, source_url TEXT, description TEXT, employment_type TEXT, start_date TEXT, deadline TEXT, custom_fields_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE RESTRICT);
CREATE INDEX idx_job_postings_company ON job_postings(company_id);
CREATE TABLE application_statuses(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, label TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, is_system INTEGER NOT NULL DEFAULT 0 CHECK(is_system IN (0,1)), is_terminal INTEGER NOT NULL DEFAULT 0 CHECK(is_terminal IN (0,1)), created_at TEXT NOT NULL);
CREATE TABLE applications(id TEXT PRIMARY KEY, applicant_profile_id TEXT, company_id TEXT, job_posting_id TEXT, status_id TEXT NOT NULL, title TEXT NOT NULL, application_date TEXT, next_follow_up_at TEXT, source TEXT, notes TEXT, custom_fields_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, FOREIGN KEY(applicant_profile_id) REFERENCES applicant_profiles(id) ON DELETE SET NULL, FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL, FOREIGN KEY(job_posting_id) REFERENCES job_postings(id) ON DELETE SET NULL, FOREIGN KEY(status_id) REFERENCES application_statuses(id) ON DELETE RESTRICT);
CREATE INDEX idx_applications_company ON applications(company_id);
CREATE INDEX idx_applications_status ON applications(status_id);
CREATE INDEX idx_applications_follow_up ON applications(next_follow_up_at);
CREATE TABLE application_contacts(application_id TEXT NOT NULL, contact_id TEXT NOT NULL, relationship_type TEXT, created_at TEXT NOT NULL, PRIMARY KEY(application_id,contact_id), FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE, FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE RESTRICT);
CREATE TABLE document_sets(id TEXT PRIMARY KEY, application_id TEXT, name TEXT NOT NULL, generation_run_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE SET NULL);
CREATE TABLE templates(id TEXT PRIMARY KEY, name TEXT NOT NULL, template_type TEXT NOT NULL CHECK(template_type IN ('document','email','workflow')), description TEXT, source_library_id TEXT, source_library_version TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX idx_templates_type ON templates(template_type);
CREATE TABLE template_versions(id TEXT PRIMARY KEY, template_id TEXT NOT NULL, version_number INTEGER NOT NULL CHECK(version_number>0), file_path TEXT, content_text TEXT, placeholders_json TEXT NOT NULL DEFAULT '[]', configuration_json TEXT NOT NULL DEFAULT '{}', content_hash TEXT, created_at TEXT NOT NULL, UNIQUE(template_id,version_number), FOREIGN KEY(template_id) REFERENCES templates(id) ON DELETE RESTRICT);
CREATE TABLE documents(id TEXT PRIMARY KEY, document_set_id TEXT, application_id TEXT, template_version_id TEXT, document_type TEXT NOT NULL, format TEXT NOT NULL CHECK(format IN ('docx','pdf','other')), file_path TEXT NOT NULL, original_filename TEXT NOT NULL, mime_type TEXT, file_size_bytes INTEGER CHECK(file_size_bytes IS NULL OR file_size_bytes>=0), file_hash TEXT, source_document_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, FOREIGN KEY(document_set_id) REFERENCES document_sets(id) ON DELETE SET NULL, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE SET NULL, FOREIGN KEY(template_version_id) REFERENCES template_versions(id) ON DELETE SET NULL, FOREIGN KEY(source_document_id) REFERENCES documents(id) ON DELETE SET NULL);
CREATE INDEX idx_documents_application ON documents(application_id);
CREATE INDEX idx_documents_set ON documents(document_set_id);
CREATE INDEX idx_documents_template_version ON documents(template_version_id);
CREATE TABLE email_signatures(id TEXT PRIMARY KEY, name TEXT NOT NULL, content_html TEXT NOT NULL DEFAULT '', content_text TEXT NOT NULL DEFAULT '', is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE UNIQUE INDEX idx_email_signatures_single_default ON email_signatures(is_default) WHERE is_default=1 AND deleted_at IS NULL;
CREATE TABLE email_provider_accounts(id TEXT PRIMARY KEY, provider TEXT NOT NULL, account_email TEXT NOT NULL, display_name TEXT, external_account_id TEXT, is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)), is_enabled INTEGER NOT NULL DEFAULT 1 CHECK(is_enabled IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(provider,account_email));
CREATE UNIQUE INDEX idx_email_accounts_single_default ON email_provider_accounts(is_default) WHERE is_default=1 AND deleted_at IS NULL;
CREATE TABLE email_drafts(id TEXT PRIMARY KEY, application_id TEXT, provider_account_id TEXT, signature_id TEXT, subject TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', body_format TEXT NOT NULL DEFAULT 'html' CHECK(body_format IN ('plain','html')), recipients_json TEXT NOT NULL DEFAULT '{}', configuration_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE SET NULL, FOREIGN KEY(provider_account_id) REFERENCES email_provider_accounts(id) ON DELETE SET NULL, FOREIGN KEY(signature_id) REFERENCES email_signatures(id) ON DELETE SET NULL);
CREATE TABLE email_jobs(id TEXT PRIMARY KEY, draft_id TEXT, application_id TEXT, provider_account_id TEXT, recipients_snapshot_json TEXT NOT NULL, subject_snapshot TEXT NOT NULL, body_snapshot TEXT NOT NULL, body_format TEXT NOT NULL CHECK(body_format IN ('plain','html')), scheduled_at_utc TEXT, timezone_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Draft','Scheduled','Queued','Sending','Sent','Failed','Cancelled','Uncertain','ReconciliationRequired')), approval_status TEXT NOT NULL DEFAULT 'pending' CHECK(approval_status IN ('not_required','pending','approved','rejected')), batch_id TEXT, idempotency_key TEXT NOT NULL UNIQUE, provider_message_id TEXT, attempt_count INTEGER NOT NULL DEFAULT 0 CHECK(attempt_count>=0), last_error_code TEXT, last_error_message TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, sent_at_utc TEXT, cancelled_at_utc TEXT, FOREIGN KEY(draft_id) REFERENCES email_drafts(id) ON DELETE SET NULL, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE SET NULL, FOREIGN KEY(provider_account_id) REFERENCES email_provider_accounts(id) ON DELETE SET NULL);
CREATE INDEX idx_email_jobs_schedule ON email_jobs(status,scheduled_at_utc);
CREATE INDEX idx_email_jobs_batch ON email_jobs(batch_id);
CREATE INDEX idx_email_jobs_application ON email_jobs(application_id);
CREATE TABLE email_attachments(id TEXT PRIMARY KEY, email_job_id TEXT NOT NULL, document_id TEXT, file_path_snapshot TEXT NOT NULL, filename_snapshot TEXT NOT NULL, mime_type_snapshot TEXT, file_hash_snapshot TEXT, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, FOREIGN KEY(email_job_id) REFERENCES email_jobs(id) ON DELETE CASCADE, FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE SET NULL);
CREATE INDEX idx_email_attachments_job ON email_attachments(email_job_id,sort_order);
CREATE TABLE email_attempts(id TEXT PRIMARY KEY, email_job_id TEXT NOT NULL, attempt_number INTEGER NOT NULL CHECK(attempt_number>0), started_at_utc TEXT NOT NULL, finished_at_utc TEXT, result TEXT NOT NULL CHECK(result IN ('Started','Sent','Failed','Uncertain','Reconciled')), provider_message_id TEXT, error_code TEXT, error_message TEXT, reconciliation_json TEXT NOT NULL DEFAULT '{}', UNIQUE(email_job_id,attempt_number), FOREIGN KEY(email_job_id) REFERENCES email_jobs(id) ON DELETE CASCADE);
CREATE INDEX idx_email_attempts_job ON email_attempts(email_job_id,attempt_number);
CREATE TABLE import_profiles(id TEXT PRIMARY KEY, name TEXT NOT NULL, file_type TEXT NOT NULL CHECK(file_type IN ('xlsx','csv')), mapping_json TEXT NOT NULL DEFAULT '{}', options_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE import_runs(id TEXT PRIMARY KEY, import_profile_id TEXT, source_filename TEXT NOT NULL, source_file_path TEXT, status TEXT NOT NULL CHECK(status IN ('Pending','Running','Completed','CompletedWithErrors','Failed','Cancelled')), total_rows INTEGER NOT NULL DEFAULT 0, processed_rows INTEGER NOT NULL DEFAULT 0, error_rows INTEGER NOT NULL DEFAULT 0, started_at TEXT, finished_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(import_profile_id) REFERENCES import_profiles(id) ON DELETE SET NULL);
CREATE TABLE import_rows(id TEXT PRIMARY KEY, import_run_id TEXT NOT NULL, row_number INTEGER NOT NULL CHECK(row_number>0), source_data_json TEXT NOT NULL DEFAULT '{}', mapped_data_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL CHECK(status IN ('Pending','Valid','Invalid','Skipped','Imported','Failed','DuplicateReview')), errors_json TEXT NOT NULL DEFAULT '[]', created_record_type TEXT, created_record_id TEXT, created_at TEXT NOT NULL, UNIQUE(import_run_id,row_number), FOREIGN KEY(import_run_id) REFERENCES import_runs(id) ON DELETE CASCADE);
CREATE INDEX idx_import_rows_run_status ON import_rows(import_run_id,status);
CREATE TABLE workflow_definitions(id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, definition_json TEXT NOT NULL DEFAULT '{}', version_number INTEGER NOT NULL DEFAULT 1 CHECK(version_number>0), is_enabled INTEGER NOT NULL DEFAULT 1 CHECK(is_enabled IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE workflow_runs(id TEXT PRIMARY KEY, workflow_definition_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Pending','Running','Paused','Completed','Failed','Cancelled')), input_json TEXT NOT NULL DEFAULT '{}', result_json TEXT NOT NULL DEFAULT '{}', current_step_id TEXT, started_at TEXT, finished_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(workflow_definition_id) REFERENCES workflow_definitions(id) ON DELETE RESTRICT);
CREATE TABLE workflow_steps(id TEXT PRIMARY KEY, workflow_run_id TEXT NOT NULL, step_key TEXT NOT NULL, step_type TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Pending','Running','Completed','Failed','Skipped','Cancelled')), input_json TEXT NOT NULL DEFAULT '{}', result_json TEXT NOT NULL DEFAULT '{}', error_message TEXT, started_at TEXT, finished_at TEXT, UNIQUE(workflow_run_id,step_key), FOREIGN KEY(workflow_run_id) REFERENCES workflow_runs(id) ON DELETE CASCADE);
CREATE INDEX idx_workflow_runs_status ON workflow_runs(status);
CREATE TABLE reminders(id TEXT PRIMARY KEY, application_id TEXT, title TEXT NOT NULL, description TEXT, due_at_utc TEXT NOT NULL, timezone_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Completed','Dismissed','Cancelled')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at_utc TEXT, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE SET NULL);
CREATE INDEX idx_reminders_due ON reminders(status,due_at_utc);
CREATE TABLE activity_log(id TEXT PRIMARY KEY, event_type TEXT NOT NULL, entity_type TEXT, entity_id TEXT, message TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE INDEX idx_activity_log_created ON activity_log(created_at);
CREATE INDEX idx_activity_log_entity ON activity_log(entity_type,entity_id);
CREATE TABLE backup_metadata(id TEXT PRIMARY KEY, file_path TEXT NOT NULL, backup_type TEXT NOT NULL CHECK(backup_type IN ('Manual','Automatic','PreMigration')), file_size_bytes INTEGER CHECK(file_size_bytes IS NULL OR file_size_bytes>=0), file_hash TEXT, encrypted INTEGER NOT NULL DEFAULT 0 CHECK(encrypted IN (0,1)), status TEXT NOT NULL CHECK(status IN ('Created','Verified','Failed','Deleted')), created_at TEXT NOT NULL, verified_at TEXT);
INSERT INTO project_metadata(key,value) VALUES ('schema_version','1'),('project_format_version','1');
